import json
import os
from pathlib import Path
import shutil
import subprocess

found = {'topics': set(), 'configs': set(), 'jars': set(), 'properties': set()}
for command, key in [('kafka-topics.sh', 'topics'), ('kafka-configs.sh', 'configs')]:
    value = shutil.which(command)
    if value:
        found[key].add(os.path.realpath(value))
for root in ['/opt', '/usr/local', '/home/ec2-user', '/home/ssm-user']:
    if not os.path.isdir(root):
        continue
    for current, directories, files in os.walk(root):
        directories[:] = [d for d in directories if d not in ('.git', '.cache', '__pycache__', 'node_modules')]
        if current.count(os.sep) - root.count(os.sep) > 8:
            directories[:] = []
        for name in files:
            full = os.path.realpath(os.path.join(current, name))
            if name == 'kafka-topics.sh':
                found['topics'].add(full)
            elif name == 'kafka-configs.sh':
                found['configs'].add(full)
            elif name.startswith('aws-msk-iam-auth-') and name.endswith('-all.jar'):
                found['jars'].add(full)
            elif name == 'client.properties':
                found['properties'].add(full)
expected = {
    'security.protocol': 'SASL_SSL',
    'sasl.mechanism': 'AWS_MSK_IAM',
    'sasl.jaas.config': 'software.amazon.msk.auth.iam.IAMLoginModule required;',
    'sasl.client.callback.handler.class': 'software.amazon.msk.auth.iam.IAMClientCallbackHandler',
}
settings = []
for name in sorted(found['properties']):
    try:
        values = {}
        for line in Path(name).read_text().splitlines():
            if '=' in line and not line.lstrip().startswith('#'):
                key, value = line.split('=', 1)
                values[key.strip()] = value.strip()
        settings.append({'path': name, 'required_settings_match': all(values.get(k) == v for k, v in expected.items()), 'credential_override_present': any(x in values.get('sasl.jaas.config', '') for x in ('awsRoleArn', 'awsProfileName', 'awsCredentialsProvider', 'awsDebugCreds')), 'unknown_keys': sorted(set(values) - set(expected))})
    except Exception:
        settings.append({'path': name, 'read_error': True})
identity = subprocess.run(['aws', 'sts', 'get-caller-identity', '--query', 'Arn', '--output', 'text'], capture_output=True, text=True, timeout=30)
print(json.dumps({'paths': {k: sorted(v) for k,v in found.items()}, 'properties': settings, 'principal_arn': identity.stdout.strip() if identity.returncode == 0 else None, 'java_present': bool(shutil.which('java')), 'javac_present': bool(shutil.which('javac')), 'credential_env_present': {k: bool(os.environ.get(k)) for k in ('AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY', 'AWS_SESSION_TOKEN', 'AWS_PROFILE', 'AWS_SHARED_CREDENTIALS_FILE', 'AWS_CONFIG_FILE', 'JAVA_TOOL_OPTIONS', 'KAFKA_OPTS')}, 'shared_credential_files_exist': [str(p) for p in (Path.home()/'.aws/credentials', Path.home()/'.aws/config') if p.exists()]}))
